CREATE TABLE person.person_activity_alignment (
    tenant_identifier                                UUID NOT NULL,
    person_activity_alignment_identifier             TEXT NOT NULL,
    person_activity_identifier                       TEXT NOT NULL,
    competency_identifier                            TEXT NOT NULL,
    skill_identifier                                 TEXT NOT NULL,
    created_by                                       BIGINT NOT NULL,
    created_date                                     TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_by                                       BIGINT,
    updated_date                                     TIMESTAMP WITH TIME ZONE,
    deleted_by                                       BIGINT,
    deleted_date                                     TIMESTAMP WITH TIME ZONE,
    competency_revision_identifier                   TEXT NOT NULL,
    CONSTRAINT pk_person_activity_alignment PRIMARY KEY (tenant_identifier, person_activity_alignment_identifier)
);
COMMENT ON TABLE person.person_activity_alignment IS 'An alignment linking a person activity to another relevant object.';
COMMENT ON COLUMN person.person_activity_alignment.tenant_identifier IS 'UUID identifying the tenant data-ownership and security boundary for this record.';
COMMENT ON COLUMN person.person_activity_alignment.person_activity_alignment_identifier IS 'Unique identifier for the competency to person activity details association';
COMMENT ON COLUMN person.person_activity_alignment.person_activity_identifier IS 'Unique identifier for learner activity details';
COMMENT ON COLUMN person.person_activity_alignment.competency_identifier IS 'Unique identifier for the competency';
COMMENT ON COLUMN person.person_activity_alignment.skill_identifier IS 'Unique identifier for skill';
COMMENT ON COLUMN person.person_activity_alignment.created_by IS 'Person identifier that created the record';
COMMENT ON COLUMN person.person_activity_alignment.created_date IS 'Date and time record was created';
COMMENT ON COLUMN person.person_activity_alignment.updated_by IS 'Person identifier that updated the record';
COMMENT ON COLUMN person.person_activity_alignment.updated_date IS 'Date and time record was updated';
COMMENT ON COLUMN person.person_activity_alignment.deleted_by IS 'Person identifier that deleted the record';
COMMENT ON COLUMN person.person_activity_alignment.deleted_date IS 'Date and time record was deleted';
COMMENT ON COLUMN person.person_activity_alignment.competency_revision_identifier IS 'Revision of the Competency referenced by this record.';

-- PersonCitizenship
-- A table that stores one or more country-specific citizenship or citizenship-like status records
-- for a person, including country, citizenship status, primary citizenship indication, effective
-- dates where known, source raw citizenship values, source lineage, and audit fields. It keeps
-- citizenship distinct from address history, residency classification, visa/immigration status,
-- and birth location.
CREATE TABLE person.person_citizenship (
    tenant_identifier                                UUID NOT NULL,
    person_identifier                                TEXT NOT NULL,
    sequence_number                                  TEXT NOT NULL,
    country_code                                     TEXT NOT NULL,
    citizenship_status_identifier                    TEXT,
    primary_citizenship_indicator                    BOOLEAN DEFAULT FALSE,
    citizenship_start_date                           DATE,
    citizenship_end_date                             DATE,
    source_raw_country_of_citizenship                TEXT,
    source_raw_citizenship_status                    TEXT,
    source_system_identifier                         TEXT,
    source_system_key_value                          TEXT,
    created_by                                       BIGINT NOT NULL,
    created_date                                     TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_by                                       BIGINT,
    updated_date                                     TIMESTAMP WITH TIME ZONE,
    deleted_by                                       BIGINT,
    deleted_date                                     TIMESTAMP WITH TIME ZONE,
    CONSTRAINT pk_person_citizenship PRIMARY KEY (tenant_identifier, person_identifier, sequence_number)
);
COMMENT ON TABLE person.person_citizenship IS 'A table that stores one or more country-specific citizenship or citizenship-like status records for a person, including country, citizenship status, primary citizenship indication, effective dates where known, source raw citizenship values, source lineage, and audit fields. It keeps citizenship distinct from address history, residency classification, visa/immigration status, and birth location.';
COMMENT ON COLUMN person.person_citizenship.tenant_identifier IS 'UUID identifying the tenant data-ownership and security boundary for this record.';
COMMENT ON COLUMN person.person_citizenship.person_identifier IS 'Tenant-scoped identifier for the person associated with the citizenship record.';
COMMENT ON COLUMN person.person_citizenship.sequence_number IS 'Sequence number distinguishing multiple citizenship records for the same person.';
COMMENT ON COLUMN person.person_citizenship.country_code IS 'ISO 3166-1 alpha-2 country or jurisdiction code for the citizenship record.';
COMMENT ON COLUMN person.person_citizenship.citizenship_status_identifier IS 'Reference-code value identifying the person''s citizenship status for the country or jurisdiction.';
COMMENT ON COLUMN person.person_citizenship.primary_citizenship_indicator IS 'Indicates whether this citizenship record is treated as the person''s primary citizenship for reporting or operational use.';
COMMENT ON COLUMN person.person_citizenship.citizenship_start_date IS 'Date on which the citizenship status or relationship began, if known.';
COMMENT ON COLUMN person.person_citizenship.citizenship_end_date IS 'Date on which the citizenship status or relationship ended, if applicable and known.';
COMMENT ON COLUMN person.person_citizenship.source_raw_country_of_citizenship IS 'Raw source-system country-of-citizenship value before canonical country mapping.';
COMMENT ON COLUMN person.person_citizenship.source_raw_citizenship_status IS 'Raw source-system citizenship status value before canonical status mapping.';
COMMENT ON COLUMN person.person_citizenship.source_system_identifier IS 'Identifier for the source system from which the citizenship record was imported, synchronized, or reconciled.';
COMMENT ON COLUMN person.person_citizenship.source_system_key_value IS 'Source-system key value for the citizenship record or source person citizenship entry.';
COMMENT ON COLUMN person.person_citizenship.created_by IS 'Person identifier that created the record';
COMMENT ON COLUMN person.person_citizenship.created_date IS 'Date and time on which the citizenship record was created.';
COMMENT ON COLUMN person.person_citizenship.updated_by IS 'Person identifier that updated the record';
COMMENT ON COLUMN person.person_citizenship.updated_date IS 'Date and time on which the citizenship record was last updated.';
COMMENT ON COLUMN person.person_citizenship.deleted_by IS 'Person identifier that deleted the record';
COMMENT ON COLUMN person.person_citizenship.deleted_date IS 'Date and time on which the citizenship record was soft-deleted.';

-- PersonCommunicationConsent
-- A table that stores person-level communication consent, opt-in, opt-out, unsubscribe, and
-- channel permission facts for channels such as email, SMS, phone, WhatsApp, or other
-- communication media. This table supports governance of whether and how the institution may
-- contact the person.
CREATE TABLE person.person_communication_consent (
    tenant_identifier                                UUID NOT NULL,
    person_identifier                                TEXT NOT NULL,
    sequence_number                                  TEXT NOT NULL,
    communication_channel_identifier                 TEXT,
    consent_status_identifier                        TEXT,
    contact_point_value                              TEXT,
    opt_in_indicator                                 BOOLEAN DEFAULT FALSE,
    opt_in_date                                      TIMESTAMP WITH TIME ZONE,
    opt_out_indicator                                BOOLEAN DEFAULT FALSE,
    opt_out_date                                     TIMESTAMP WITH TIME ZONE,
    unsubscribe_date                                 TIMESTAMP WITH TIME ZONE,
    consent_source_identifier                        TEXT,
    source_raw_communication_channel                 TEXT,
    source_raw_consent_status                        TEXT,
    source_raw_opt_in_value                          TEXT,
    source_raw_opt_out_value                         TEXT,
    source_raw_contact_point                         TEXT,
    source_system_identifier                         TEXT,
    source_system_key_value                          TEXT,
    created_by                                       BIGINT NOT NULL,
    created_date                                     TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_by                                       BIGINT,
    updated_date                                     TIMESTAMP WITH TIME ZONE,
    deleted_by                                       BIGINT,
    deleted_date                                     TIMESTAMP WITH TIME ZONE,
    CONSTRAINT pk_person_communication_consent PRIMARY KEY (tenant_identifier, person_identifier, sequence_number)
);
COMMENT ON TABLE person.person_communication_consent IS 'A table that stores person-level communication consent, opt-in, opt-out, unsubscribe, and channel permission facts for channels such as email, SMS, phone, WhatsApp, or other communication media. This table supports governance of whether and how the institution may contact the person.';
COMMENT ON COLUMN person.person_communication_consent.tenant_identifier IS 'UUID identifying the tenant data-ownership and security boundary for this record.';
COMMENT ON COLUMN person.person_communication_consent.person_identifier IS 'Tenant-scoped person identifier to whom the consent/subscription fact belongs.';
COMMENT ON COLUMN person.person_communication_consent.sequence_number IS 'Sequence number for multiple communication consent rows for the person.';
COMMENT ON COLUMN person.person_communication_consent.communication_channel_identifier IS 'Reference-code value identifying the communication channel, such as email, SMS, or WhatsApp.';
COMMENT ON COLUMN person.person_communication_consent.consent_status_identifier IS 'Reference-code value identifying the consent, subscription, or opt-in/opt-out status.';
COMMENT ON COLUMN person.person_communication_consent.contact_point_value IS 'Email address, phone number, WhatsApp number, or other contact point associated with the consent fact.';
COMMENT ON COLUMN person.person_communication_consent.opt_in_indicator IS 'Indicates whether the person is recorded as opted in for the channel/contact point.';
COMMENT ON COLUMN person.person_communication_consent.opt_in_date IS 'Date and time the opt-in was recorded or became effective.';
COMMENT ON COLUMN person.person_communication_consent.opt_out_indicator IS 'Indicates whether the person is recorded as opted out for the channel/contact point.';
COMMENT ON COLUMN person.person_communication_consent.opt_out_date IS 'Date and time the opt-out was recorded or became effective.';
COMMENT ON COLUMN person.person_communication_consent.unsubscribe_date IS 'Date and time the person unsubscribed from the channel/contact point.';
COMMENT ON COLUMN person.person_communication_consent.consent_source_identifier IS 'Reference-code value identifying the source or mechanism of consent where needed.';
COMMENT ON COLUMN person.person_communication_consent.source_raw_communication_channel IS 'Source-system communication channel value preserved when canonical mapping is lossy.';
COMMENT ON COLUMN person.person_communication_consent.source_raw_consent_status IS 'Source-system consent/subscription status preserved when canonical mapping is lossy.';
COMMENT ON COLUMN person.person_communication_consent.source_raw_opt_in_value IS 'Source-system opt-in value preserved as supplied.';
COMMENT ON COLUMN person.person_communication_consent.source_raw_opt_out_value IS 'Source-system opt-out value preserved as supplied.';
COMMENT ON COLUMN person.person_communication_consent.source_raw_contact_point IS 'Source-system contact point value preserved as supplied.';
COMMENT ON COLUMN person.person_communication_consent.source_system_identifier IS 'Source system from which the consent row originated or can be reconciled.';
COMMENT ON COLUMN person.person_communication_consent.source_system_key_value IS 'Source-system key value for the consent row.';
COMMENT ON COLUMN person.person_communication_consent.created_by IS 'Person identifier that created the record';
COMMENT ON COLUMN person.person_communication_consent.created_date IS 'Date and time record was created';
COMMENT ON COLUMN person.person_communication_consent.updated_by IS 'Person identifier that updated the record';
COMMENT ON COLUMN person.person_communication_consent.updated_date IS 'Date and time record was updated';
COMMENT ON COLUMN person.person_communication_consent.deleted_by IS 'Person identifier that deleted the record';
COMMENT ON COLUMN person.person_communication_consent.deleted_date IS 'Date and time record was deleted';

-- PersonCommunicationDeliverabilityEvent
-- A table that stores communication deliverability events associated with a person and channel,
-- such as hard bounce, soft bounce, invalid address/number, unsubscribe event, suppression,
-- delivery failure, or provider error. This table records what happened to communication attempts
-- or channel reachability without becoming a full message-history table.
CREATE TABLE person.person_communication_deliverability_event (
    tenant_identifier                                UUID NOT NULL,
    person_identifier                                TEXT NOT NULL,
    sequence_number                                  TEXT NOT NULL,
    communication_channel_identifier                 TEXT,
    deliverability_event_type_identifier             TEXT,
    deliverability_event_date                        TIMESTAMP WITH TIME ZONE,
    contact_point_value                              TEXT,
    error_code                                       TEXT,
    error_description                                TEXT,
    source_raw_communication_channel                 TEXT,
    source_raw_deliverability_event_type             TEXT,
    source_raw_contact_point                         TEXT,
    source_system_identifier                         TEXT,
    source_system_key_value                          TEXT,
    created_by                                       BIGINT NOT NULL,
    created_date                                     TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_by                                       BIGINT,
    updated_date                                     TIMESTAMP WITH TIME ZONE,
    deleted_by                                       BIGINT,
    deleted_date                                     TIMESTAMP WITH TIME ZONE,
    CONSTRAINT pk_person_communication_deliverability_event PRIMARY KEY (tenant_identifier, person_identifier, sequence_number)
);
COMMENT ON TABLE person.person_communication_deliverability_event IS 'A table that stores communication deliverability events associated with a person and channel, such as hard bounce, soft bounce, invalid address/number, unsubscribe event, suppression, delivery failure, or provider error. This table records what happened to communication attempts or channel reachability without becoming a full message-history table.';
COMMENT ON COLUMN person.person_communication_deliverability_event.tenant_identifier IS 'UUID identifying the tenant data-ownership and security boundary for this record.';
COMMENT ON COLUMN person.person_communication_deliverability_event.person_identifier IS 'Tenant-scoped person identifier to whom the deliverability event belongs.';
COMMENT ON COLUMN person.person_communication_deliverability_event.sequence_number IS 'Sequence number for multiple deliverability event rows for the person.';
COMMENT ON COLUMN person.person_communication_deliverability_event.communication_channel_identifier IS 'Reference-code value identifying the communication channel, such as email or SMS.';
COMMENT ON COLUMN person.person_communication_deliverability_event.deliverability_event_type_identifier IS 'Reference-code value identifying the type of deliverability event, such as hard bounce or invalid contact point.';
COMMENT ON COLUMN person.person_communication_deliverability_event.deliverability_event_date IS 'Date and time the deliverability event occurred or was recorded.';
COMMENT ON COLUMN person.person_communication_deliverability_event.contact_point_value IS 'Email address, phone number, or other contact point associated with the deliverability event.';
COMMENT ON COLUMN person.person_communication_deliverability_event.error_code IS 'Source or platform error code associated with the deliverability event.';
COMMENT ON COLUMN person.person_communication_deliverability_event.error_description IS 'Source or platform description of the deliverability event or error.';
COMMENT ON COLUMN person.person_communication_deliverability_event.source_raw_communication_channel IS 'Source-system communication channel value preserved when canonical mapping is lossy.';
COMMENT ON COLUMN person.person_communication_deliverability_event.source_raw_deliverability_event_type IS 'Source-system deliverability event type preserved when canonical mapping is lossy.';
COMMENT ON COLUMN person.person_communication_deliverability_event.source_raw_contact_point IS 'Source-system contact point value preserved as supplied.';
COMMENT ON COLUMN person.person_communication_deliverability_event.source_system_identifier IS 'Source system from which the deliverability event row originated or can be reconciled.';
COMMENT ON COLUMN person.person_communication_deliverability_event.source_system_key_value IS 'Source-system key value for the deliverability event row.';
COMMENT ON COLUMN person.person_communication_deliverability_event.created_by IS 'Person identifier that created the record';
COMMENT ON COLUMN person.person_communication_deliverability_event.created_date IS 'Date and time record was created';
COMMENT ON COLUMN person.person_communication_deliverability_event.updated_by IS 'Person identifier that updated the record';
COMMENT ON COLUMN person.person_communication_deliverability_event.updated_date IS 'Date and time record was updated';
COMMENT ON COLUMN person.person_communication_deliverability_event.deleted_by IS 'Person identifier that deleted the record';
COMMENT ON COLUMN person.person_communication_deliverability_event.deleted_date IS 'Date and time record was deleted';

-- PersonDemographics
-- A tenant-scoped table containing person-specific demographic characteristics and summary/legacy
-- demographic attributes. Governed gender identity is modeled separately through
-- PersonGenderIdentity; the legacy Gender text remains for compatibility where needed.
CREATE TABLE person.person_demographics (
    tenant_identifier                                UUID NOT NULL,
    person_identifier                                TEXT NOT NULL,
    person_demographics_identifier                   TEXT NOT NULL,
    information_source_organization_identifier       TEXT,
    source_system_identifier                         TEXT,
    dependency_status                                TEXT,
    emancipated_minor                                BOOLEAN,
    birth_date                                       DATE,
    person_date_entered_us                           DATE,
    birth_city                                       TEXT,
    birth_state_province                             TEXT,
    country_of_birth_code                            TEXT,
    economic_disadvantage_status_indicator           BOOLEAN NOT NULL DEFAULT FALSE,
    economic_disadvantage_status_start_date          DATE,
    economic_disadvantage_status_end_date            DATE,
    federal_race_and_ethnicity_declined_indicator    BOOLEAN NOT NULL DEFAULT FALSE,
    hispanic_or_latino_ethnicity_indicator           BOOLEAN,
    gender                                           TEXT,
    sex                                              TEXT,
    marital_status                                   TEXT,
    military_active_student_indicator                TEXT,
    military_branch                                  TEXT,
    native_language                                  TEXT,
    number_of_household_college_students             INTEGER,
    number_of_people_in_household                    INTEGER,
    transgender_indicator                            BOOLEAN,
    tribal_id_or_cib                                 TEXT,
    pronouns                                         TEXT,
    military_veteran_student_indicator               TEXT,
    source_system_key_value                          TEXT,
    source_system_created_date                       DATE,
    source_system_updated_date                       DATE,
    source_system_deleted_date                       DATE,
    created_by                                       BIGINT NOT NULL,
    created_date                                     TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_by                                       BIGINT,
    updated_date                                     TIMESTAMP WITH TIME ZONE,
    deleted_by                                       BIGINT,
    deleted_date                                     TIMESTAMP WITH TIME ZONE,
    marital_status_identifier                        TEXT,
    source_raw_marital_category                      TEXT,
    personal_pronoun_identifier                      TEXT,
    CONSTRAINT pk_person_demographics PRIMARY KEY (tenant_identifier, person_demographics_identifier)
);
COMMENT ON TABLE person.person_demographics IS 'A tenant-scoped table containing person-specific demographic characteristics and summary/legacy demographic attributes. Governed gender identity is modeled separately through PersonGenderIdentity; the legacy Gender text remains for compatibility where needed.';
COMMENT ON COLUMN person.person_demographics.tenant_identifier IS 'UUID identifying the tenant data-ownership and security boundary for this record.';
COMMENT ON COLUMN person.person_demographics.person_identifier IS 'A unique number or alphanumeric code assigned to a person';
COMMENT ON COLUMN person.person_demographics.person_demographics_identifier IS 'Unique identifier for the person''s demographic information';
COMMENT ON COLUMN person.person_demographics.information_source_organization_identifier IS 'Organization identifier for the source of the information provided';
COMMENT ON COLUMN person.person_demographics.source_system_identifier IS 'Unique identifier for the source system';
COMMENT ON COLUMN person.person_demographics.dependency_status IS 'A person''s classification as dependent or independent with regards to eligibility for Title IV Federal Student aid';
COMMENT ON COLUMN person.person_demographics.emancipated_minor IS 'A minor student under the age of 18 who has been granted by legal action to have the power and capacity of an adult';
COMMENT ON COLUMN person.person_demographics.birth_date IS 'Person date of birth';
COMMENT ON COLUMN person.person_demographics.person_date_entered_us IS 'For students born outside of the U.S., the date the student entered the U.S.';
COMMENT ON COLUMN person.person_demographics.birth_city IS 'The city or locality in which the person was born';
COMMENT ON COLUMN person.person_demographics.birth_state_province IS 'The state, province, territory, or comparable first-level jurisdiction in which the person was born';
COMMENT ON COLUMN person.person_demographics.country_of_birth_code IS 'The ISO 3166-1 alpha-2 code for the country in which the person was born';
COMMENT ON COLUMN person.person_demographics.economic_disadvantage_status_indicator IS 'An indication that the student met the State criteria for classification as having an economic disadvantage';
COMMENT ON COLUMN person.person_demographics.economic_disadvantage_status_start_date IS 'The beginning year, month and day when the economic disadvantage status became applicable to an individual';
COMMENT ON COLUMN person.person_demographics.economic_disadvantage_status_end_date IS 'The ending year, month and day when the economic disadvantage status applied to an individual';
COMMENT ON COLUMN person.person_demographics.federal_race_and_ethnicity_declined_indicator IS 'A parent, guardian, or student declined to report sufficient information for identifying a student''s federal race and/or ethnicity';
COMMENT ON COLUMN person.person_demographics.hispanic_or_latino_ethnicity_indicator IS 'The person''s collected or resolved response to the U.S. Hispanic-or-Latino ethnicity question, maintained separately from race selections; this is not a complete representation of ethnicity.';
COMMENT ON COLUMN person.person_demographics.gender IS 'Legacy or source-provided gender text retained for compatibility. Governed gender identity is represented through PersonGenderIdentity; legal sex remains a separate concept.';
COMMENT ON COLUMN person.person_demographics.sex IS 'The concept describing the biological traits that distinguish the males and females of a species';
COMMENT ON COLUMN person.person_demographics.marital_status IS 'The marital status of the person as of today';
COMMENT ON COLUMN person.person_demographics.military_active_student_indicator IS 'An indication that the student is currently serving on Active Duty, in the National Guard, or in the Reserve components of the United States military resources (e.g. Active, NotActive, Unknown)';
COMMENT ON COLUMN person.person_demographics.military_branch IS 'A branch of the US Military applicable for specifying more details when using Military Connected Student Indicator, Military Active Student Indicator, Military Veteran Student Indicator, and Military Enlistment After Exit elements';
COMMENT ON COLUMN person.person_demographics.native_language IS 'Native language to interact in oral and written communication';
COMMENT ON COLUMN person.person_demographics.number_of_household_college_students IS 'Number of people, including the student, who will attend at least half-time in the current academic year, a program that leads to a college degree or certificate';
COMMENT ON COLUMN person.person_demographics.number_of_people_in_household IS 'Total number of persons residing in the same household';
COMMENT ON COLUMN person.person_demographics.transgender_indicator IS 'Indicates whether the student is transgender or not or prefers not to answer';
COMMENT ON COLUMN person.person_demographics.tribal_id_or_cib IS 'Identification issued by tribe indicating enrollment or membership in the tribe or the identification of the Certificate of Degree of Indian Blood (CDIB/CIB)';
COMMENT ON COLUMN person.person_demographics.pronouns IS 'Preferred pronouns of person';
COMMENT ON COLUMN person.person_demographics.military_veteran_student_indicator IS 'An indication that the student is a veteran who served on Active Duty, in the National Guard, or in the Reserve components of the United States military resources (e.g. Veteran, NotVeteran, Unknown)';
COMMENT ON COLUMN person.person_demographics.source_system_key_value IS 'Unique identifier of this record in the source system';
COMMENT ON COLUMN person.person_demographics.source_system_created_date IS 'Date the record was created in the source system';
COMMENT ON COLUMN person.person_demographics.source_system_updated_date IS 'Date the record was last updated in the source system';
COMMENT ON COLUMN person.person_demographics.source_system_deleted_date IS 'Date the record was deleted from the source system';
COMMENT ON COLUMN person.person_demographics.created_by IS 'Person identifier that created the record';
COMMENT ON COLUMN person.person_demographics.created_date IS 'Date and time record was created';
COMMENT ON COLUMN person.person_demographics.updated_by IS 'Person identifier that updated the record';
COMMENT ON COLUMN person.person_demographics.updated_date IS 'Date and time record was updated';
COMMENT ON COLUMN person.person_demographics.deleted_by IS 'Person identifier that deleted the record';
COMMENT ON COLUMN person.person_demographics.deleted_date IS 'Date and time record was deleted';
COMMENT ON COLUMN person.person_demographics.marital_status_identifier IS 'Governed current marital status.';
COMMENT ON COLUMN person.person_demographics.source_raw_marital_category IS 'Raw source marital category.';
COMMENT ON COLUMN person.person_demographics.personal_pronoun_identifier IS 'Governed preferred personal pronoun.';

-- PersonDocument
-- A table containing details about documents that have been saved for a person, including links to
-- the authoritative document.
CREATE TABLE person.person_document (
    tenant_identifier                                UUID NOT NULL,
    person_identifier                                TEXT NOT NULL,
    person_document_identifier                       TEXT NOT NULL,
    person_document_author_identifier                TEXT NOT NULL,
    learner_financial_aid_application_identifier     TEXT,
    source_system_identifier                         TEXT,
    description                                      TEXT,
    status                                           TEXT NOT NULL,
    type                                             TEXT,
    document_name                                    TEXT NOT NULL,
    size                                             NUMERIC,
    url                                              TEXT,
    record_name                                      TEXT NOT NULL,
    visible_indicator                                BOOLEAN NOT NULL DEFAULT FALSE,
    mime_type                                        TEXT,
    waive_right_to_access_indicator                  BOOLEAN,
    exclude_from_learner_financial_aid_indicator     BOOLEAN,
    financial_aid_document_status                    TEXT,
    completion_status                                TEXT,
    source_system_key_value                          TEXT,
    source_system_created_date                       DATE,
    source_system_updated_date                       DATE,
    source_system_deleted_date                       DATE,
    created_by                                       BIGINT NOT NULL,
    created_date                                     TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_by                                       BIGINT,
    updated_date                                     TIMESTAMP WITH TIME ZONE,
    deleted_by                                       BIGINT,
    deleted_date                                     TIMESTAMP WITH TIME ZONE,
    CONSTRAINT pk_person_document PRIMARY KEY (tenant_identifier, person_document_identifier)
);
COMMENT ON TABLE person.person_document IS 'A table containing details about documents that have been saved for a person, including links to the authoritative document.';
COMMENT ON COLUMN person.person_document.tenant_identifier IS 'UUID identifying the tenant data-ownership and security boundary for this record.';
COMMENT ON COLUMN person.person_document.person_identifier IS 'A unique number or alphanumeric code assigned to a person';
COMMENT ON COLUMN person.person_document.person_document_identifier IS 'Unique identifier for a person''s document';
COMMENT ON COLUMN person.person_document.person_document_author_identifier IS 'Person identifier of the person who authored document';
COMMENT ON COLUMN person.person_document.learner_financial_aid_application_identifier IS 'Unique identifier for the FAFSA or other financial aid application';
COMMENT ON COLUMN person.person_document.source_system_identifier IS 'Unique identifier for the source system';
COMMENT ON COLUMN person.person_document.description IS 'Description of the file stored for a person';
COMMENT ON COLUMN person.person_document.status IS 'Indicates whether the document is active, inactive, archived, etc.';
COMMENT ON COLUMN person.person_document.type IS 'Specifies a short description of the data in the document';
COMMENT ON COLUMN person.person_document.document_name IS 'Name of the file stored for the person';
COMMENT ON COLUMN person.person_document.size IS 'Size of the file stored in kilobytes for the person';
COMMENT ON COLUMN person.person_document.url IS 'URL path for the file stored for the person';
COMMENT ON COLUMN person.person_document.record_name IS 'A name for the record';
COMMENT ON COLUMN person.person_document.visible_indicator IS 'Indicator that a document should be visible to others besides the author and learner';
COMMENT ON COLUMN person.person_document.mime_type IS 'Indicates the nature and format of the document or file as defined and standardized in IETF''s RFC 6838';
COMMENT ON COLUMN person.person_document.waive_right_to_access_indicator IS 'Indicator that a student waived the right to access a letter of recommendation';
COMMENT ON COLUMN person.person_document.exclude_from_learner_financial_aid_indicator IS 'Indicator that the students wants to exclude the letter of recommendation in their scholarship application';
COMMENT ON COLUMN person.person_document.financial_aid_document_status IS 'Status of a document submitted with the financial aid application';
COMMENT ON COLUMN person.person_document.completion_status IS 'Indicates how far along a document is in the process of being authored';
COMMENT ON COLUMN person.person_document.source_system_key_value IS 'Unique identifier of this record in the source system';
COMMENT ON COLUMN person.person_document.source_system_created_date IS 'Date the record was created in the source system';
COMMENT ON COLUMN person.person_document.source_system_updated_date IS 'Date the record was last updated in the source system';
COMMENT ON COLUMN person.person_document.source_system_deleted_date IS 'Date the record was deleted from the source system';
COMMENT ON COLUMN person.person_document.created_by IS 'Person identifier that created the record';
COMMENT ON COLUMN person.person_document.created_date IS 'Date and time record was created';
COMMENT ON COLUMN person.person_document.updated_by IS 'Person identifier that updated the record';
COMMENT ON COLUMN person.person_document.updated_date IS 'Date and time record was updated';
COMMENT ON COLUMN person.person_document.deleted_by IS 'Person identifier that deleted the record';
