-- PersonImmigrationStatus
-- A table that stores visa, immigration, permit, and study/work authorization facts for a person,
-- including broad immigration status type, visa type, visa status, visa-required and visa-holder
-- indicators, issuing country, issue and expiration dates, effective dates, source raw
-- immigration/visa values, source lineage, and audit fields. It keeps immigration and visa facts
-- distinct from citizenship, address history, residency classification, and birth location.
CREATE TABLE person.person_immigration_status (
    tenant_identifier                                UUID NOT NULL,
    person_identifier                                TEXT NOT NULL,
    sequence_number                                  TEXT NOT NULL,
    immigration_status_type_identifier               TEXT NOT NULL,
    visa_type_identifier                             TEXT,
    visa_status_identifier                           TEXT,
    visa_required_indicator                          BOOLEAN,
    visa_holder_indicator                            BOOLEAN,
    visa_issuing_country_code                        TEXT,
    visa_issued_date                                 DATE,
    visa_expiration_date                             DATE,
    immigration_status_start_date                    DATE,
    immigration_status_end_date                      DATE,
    source_raw_immigration_status_type               TEXT,
    source_raw_visa_type                             TEXT,
    source_raw_visa_status                           TEXT,
    source_raw_visa_required                         TEXT,
    source_system_identifier                         TEXT,
    source_system_key_value                          TEXT,
    created_by                                       BIGINT NOT NULL,
    created_date                                     TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_by                                       BIGINT,
    updated_date                                     TIMESTAMP WITH TIME ZONE,
    deleted_by                                       BIGINT,
    deleted_date                                     TIMESTAMP WITH TIME ZONE,
    CONSTRAINT pk_person_immigration_status PRIMARY KEY (tenant_identifier, person_identifier, sequence_number)
);
COMMENT ON TABLE person.person_immigration_status IS 'A table that stores visa, immigration, permit, and study/work authorization facts for a person, including broad immigration status type, visa type, visa status, visa-required and visa-holder indicators, issuing country, issue and expiration dates, effective dates, source raw immigration/visa values, source lineage, and audit fields. It keeps immigration and visa facts distinct from citizenship, address history, residency classification, and birth location.';
COMMENT ON COLUMN person.person_immigration_status.tenant_identifier IS 'UUID identifying the tenant data-ownership and security boundary for this record.';
COMMENT ON COLUMN person.person_immigration_status.person_identifier IS 'Tenant-scoped identifier for the person associated with the immigration-status record.';
COMMENT ON COLUMN person.person_immigration_status.sequence_number IS 'Sequence number distinguishing multiple immigration-status records for the same person.';
COMMENT ON COLUMN person.person_immigration_status.immigration_status_type_identifier IS 'Reference-code value identifying the broad immigration, permit, or authorization classification being recorded.';
COMMENT ON COLUMN person.person_immigration_status.visa_type_identifier IS 'Reference-code value identifying the visa type where a visa-specific fact is recorded.';
COMMENT ON COLUMN person.person_immigration_status.visa_status_identifier IS 'Reference-code value identifying the high-level status of the visa or visa-related record.';
COMMENT ON COLUMN person.person_immigration_status.visa_required_indicator IS 'Indicates whether the person is recorded as requiring a visa for the relevant study, work, enrollment, or institutional context.';
COMMENT ON COLUMN person.person_immigration_status.visa_holder_indicator IS 'Indicates whether the person is recorded as holding a visa in the relevant source or institutional context.';
COMMENT ON COLUMN person.person_immigration_status.visa_issuing_country_code IS 'ISO 3166-1 alpha-2 code for the country or jurisdiction that issued the visa, where known.';
COMMENT ON COLUMN person.person_immigration_status.visa_issued_date IS 'Date on which the visa was issued, where known.';
COMMENT ON COLUMN person.person_immigration_status.visa_expiration_date IS 'Date on which the visa expires, where applicable and known.';
COMMENT ON COLUMN person.person_immigration_status.immigration_status_start_date IS 'Date on which the immigration-status or authorization classification began, where known.';
COMMENT ON COLUMN person.person_immigration_status.immigration_status_end_date IS 'Date on which the immigration-status or authorization classification ended, where applicable and known.';
COMMENT ON COLUMN person.person_immigration_status.source_raw_immigration_status_type IS 'Raw source-system immigration-status or authorization type before canonical mapping.';
COMMENT ON COLUMN person.person_immigration_status.source_raw_visa_type IS 'Raw source-system visa type before canonical mapping.';
COMMENT ON COLUMN person.person_immigration_status.source_raw_visa_status IS 'Raw source-system visa status before canonical mapping.';
COMMENT ON COLUMN person.person_immigration_status.source_raw_visa_required IS 'Raw source-system visa-required value before canonical interpretation.';
COMMENT ON COLUMN person.person_immigration_status.source_system_identifier IS 'Identifier for the source system from which the immigration-status record was imported, synchronized, or reconciled.';
COMMENT ON COLUMN person.person_immigration_status.source_system_key_value IS 'Source-system key value for the immigration-status record or source person immigration entry.';
COMMENT ON COLUMN person.person_immigration_status.created_by IS 'Person identifier that created the record';
COMMENT ON COLUMN person.person_immigration_status.created_date IS 'Date and time on which the immigration-status record was created.';
COMMENT ON COLUMN person.person_immigration_status.updated_by IS 'Person identifier that updated the record';
COMMENT ON COLUMN person.person_immigration_status.updated_date IS 'Date and time on which the immigration-status record was last updated.';
COMMENT ON COLUMN person.person_immigration_status.deleted_by IS 'Person identifier that deleted the record';
COMMENT ON COLUMN person.person_immigration_status.deleted_date IS 'Date and time on which the immigration-status record was soft-deleted.';

