    children_of_fallen_heroes_indicator              BOOLEAN NOT NULL DEFAULT FALSE,
    first_generation_college_student                 BOOLEAN DEFAULT FALSE,
    homelessness_status_indicator                    BOOLEAN NOT NULL DEFAULT FALSE,
    homelessness_status_start_date                   DATE,
    homelessness_status_end_date                     DATE,
    agriculture_migrant_status_indicator             BOOLEAN NOT NULL DEFAULT FALSE,
    public_assistance_status_indicator               BOOLEAN NOT NULL DEFAULT FALSE,
    maternal_guardian_education                      TEXT,
    naspa_first_generation_college_student           TEXT,
    incarcerated_status                              TEXT,
    orphan_status_indicator                          BOOLEAN,
    orphan_status_start_date                         DATE,
    orphan_status_end_date                           DATE,
    ward_of_the_court_status_indicator               BOOLEAN,
    ward_of_the_court_start_date                     DATE,
    ward_of_the_court_end_date                       DATE,
    foster_care_status_indicator                     BOOLEAN,
    foster_care_status_start_date                    DATE,
    foster_care_status_end_date                      DATE,
    guardianship_status_indicator                    BOOLEAN,
    self_supporting_status_indicator                 BOOLEAN,
    unusual_circumstances_status_indicator           BOOLEAN,
    parent_marital_status_indicator                  BOOLEAN,
    parent_unwilling_to_provide_fafsa_information_indicator BOOLEAN,
    education_verification_method                    TEXT,
    homeless_primary_residence                       TEXT,
    education_highest_level                          TEXT,
    source_system_key_value                          TEXT,
    source_system_created_date                       DATE,
    source_system_updated_date                       DATE,
    source_system_deleted_date                       DATE,
    created_by                                       BIGINT NOT NULL,
    created_date                                     TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_by                                       BIGINT,
    updated_date                                     TIMESTAMP WITH TIME ZONE,
    deleted_by                                       BIGINT,
    deleted_date                                     TIMESTAMP WITH TIME ZONE,
    CONSTRAINT pk_person_non_identifiable_demographics PRIMARY KEY (tenant_identifier, person_non_identifiable_demographics_identifier)
);
COMMENT ON TABLE person.person_non_identifiable_demographics IS 'A table containing details about a the non-identifiable demographics as reported by the learner.';
COMMENT ON COLUMN person.person_non_identifiable_demographics.tenant_identifier IS 'UUID identifying the tenant data-ownership and security boundary for this record.';
COMMENT ON COLUMN person.person_non_identifiable_demographics.person_identifier IS 'A unique number or alphanumeric code assigned to a person';
COMMENT ON COLUMN person.person_non_identifiable_demographics.person_non_identifiable_demographics_identifier IS 'Unique identifier for the person''s non-identifiable demographic information';
COMMENT ON COLUMN person.person_non_identifiable_demographics.information_source_organization_identifier IS 'Organization identifier for the source of the information provided';
COMMENT ON COLUMN person.person_non_identifiable_demographics.source_system_identifier IS 'Unique identifier for the source system';
COMMENT ON COLUMN person.person_non_identifiable_demographics.number_of_dependents IS 'The number of dependents who live with the student and receive more than half their support from them';
COMMENT ON COLUMN person.person_non_identifiable_demographics.number_of_dependents_type IS 'The student''s relationship to the dependents who live with the student or receive more than half of the student''s support';
COMMENT ON COLUMN person.person_non_identifiable_demographics.paternal_guardian_education IS 'The highest level of education attained by a person''s father or paternal guardian';
COMMENT ON COLUMN person.person_non_identifiable_demographics.single_parent_or_single_pregnant_woman_status_indicator IS 'A student who, at some time during the school year, is either a pregnant female student who is unmarried; or a male or female student who is unmarried or legally separated from a spouse and has a minor child or children';
COMMENT ON COLUMN person.person_non_identifiable_demographics.children_of_fallen_heroes_indicator IS 'Pell-eligible students whose parent or guardian was a member of the US armed forces and died as a result of military resource performed in Iraq or Afghanistan after the events of 9/11 or a public safety officer and died as a result of active resource in the line of duty At the time of the parent''s or guardian''s death, the student must be less than 24 years of age or enrolled in college or career school at least part-time';
COMMENT ON COLUMN person.person_non_identifiable_demographics.first_generation_college_student IS 'The term First Generation College Student means an individual both of whose parents did not complete a baccalaureate degree or in the case of any individual who regularly resided with and received support from only one parent, an individual whose only such parent did not complete a baccalaureate degree';
COMMENT ON COLUMN person.person_non_identifiable_demographics.homelessness_status_indicator IS 'Children and youth who lack a fixed, regular, and adequate nighttime residence Homeless children and youth include: 1) children and youth who are sharing the housing of other persons due to loss of housing, economic hardship, or a similar reason; are living in motels, hotels, trailer parks, or camping grounds due to the lack of alternative adequate accommodations; are living in emergency or transitional shelters; are abandoned in hospitals; or are awaiting foster care placement; 2) children and youth who have a primary nighttime residence that is a public or private place not designed for or originally used as a regular sleeping accommodation for human beings; or 3) children and youths who are living in cars, parks, public spaces, abandoned buildings, substandard housing, bus or train stations, or similar settings 4) migratory children who qualify as homeless because the children are living in circumstances described in the above (See Section 103 of the McKinney Act for a more detailed description of this data element)';
COMMENT ON COLUMN person.person_non_identifiable_demographics.homelessness_status_start_date IS 'Indicates the month, day, and year upon which the student began being homeless';
COMMENT ON COLUMN person.person_non_identifiable_demographics.homelessness_status_end_date IS 'Indicates the month, day, and year upon which the student stopped being homeless';
COMMENT ON COLUMN person.person_non_identifiable_demographics.agriculture_migrant_status_indicator IS 'Persons who are, or whose parents or spouses are, migratory agricultural workers, including migratory dairy workers, or migratory fishers, and who, in the preceding 36 months, in order to obtain, or accompany such parents or spouses, in order to obtain, temporary or seasonal employment in agricultural or fishing work (A) have moved from one LEA to another; (B) in a state that comprises a single LEA, have moved from one administrative area to another within such LEA; or (C) reside in an LEA of more than 15,000 square miles, and migrate a distance of 20 miles or more to a temporary residence to engage in a fishing activity';
COMMENT ON COLUMN person.person_non_identifiable_demographics.public_assistance_status_indicator IS 'A person who receives financial assistance from Federal, State, or local government agencies, including Temporary Assistance for Needy Families or equivalent';
COMMENT ON COLUMN person.person_non_identifiable_demographics.maternal_guardian_education IS 'The highest level of education attained by a person''s mother or maternal guardian';
COMMENT ON COLUMN person.person_non_identifiable_demographics.naspa_first_generation_college_student IS 'Indicates NASPA''s coding for first generation status of the student';
COMMENT ON COLUMN person.person_non_identifiable_demographics.incarcerated_status IS 'Indicates person''s incarceration status';
COMMENT ON COLUMN person.person_non_identifiable_demographics.orphan_status_indicator IS 'Indicates whether or not the person is or was an orphan (no living or biological parent)';
COMMENT ON COLUMN person.person_non_identifiable_demographics.orphan_status_start_date IS 'Indicates the month, day, and year that the person became an orphan (no living or biological parent)';
COMMENT ON COLUMN person.person_non_identifiable_demographics.orphan_status_end_date IS 'Indicates the month, day, and year that the person was no longer an orphan (no living or biological parent)';
COMMENT ON COLUMN person.person_non_identifiable_demographics.ward_of_the_court_status_indicator IS 'Indicates whether or not the person is or was a ward of the court';
COMMENT ON COLUMN person.person_non_identifiable_demographics.ward_of_the_court_start_date IS 'Indicates the month, day, and year that the person became a ward of the court';
COMMENT ON COLUMN person.person_non_identifiable_demographics.ward_of_the_court_end_date IS 'Indicates the month, day, and year that the person was no longer a ward of the court';
COMMENT ON COLUMN person.person_non_identifiable_demographics.foster_care_status_indicator IS 'Indicates whether or not the person is or was in foster care';
COMMENT ON COLUMN person.person_non_identifiable_demographics.foster_care_status_start_date IS 'Indicates the month, day, and year that the person began foster care';
COMMENT ON COLUMN person.person_non_identifiable_demographics.foster_care_status_end_date IS 'Indicates the month, day, and year that the person was no longer in foster care';
COMMENT ON COLUMN person.person_non_identifiable_demographics.guardianship_status_indicator IS 'Indicates whether the student is or was in a legal guardianship with someone other than their parent or stepparent, as determined by a court in their state of residence';
COMMENT ON COLUMN person.person_non_identifiable_demographics.self_supporting_status_indicator IS 'Indicates whether, at any time on or after July 1, the student was unaccompanied and either (1) homeless or (2) self-supporting and at risk of being homeless';
COMMENT ON COLUMN person.person_non_identifiable_demographics.unusual_circumstances_status_indicator IS 'Indicates whether unusual circumstances prevent the student from contacting their parents or whether contacting their parents pose a risk to the student. A student may be experiencing unusual circumstances if they: left home due to an abusive or threatening environment; are abandoned by or estranged from their parents and have not been adopted; have refugee or asylee status and are separated from their parents, or their parents are displaced in a foreign country; are a victim of human trafficking; are incarcerated, or their parents are incarcerated and contact with the parents would pose a risk to the student; or are otherwise unable to contact or locate their parents and have not been adopted.';
COMMENT ON COLUMN person.person_non_identifiable_demographics.parent_marital_status_indicator IS 'Indicates whether or not the student''s parents are married to each other';
COMMENT ON COLUMN person.person_non_identifiable_demographics.parent_unwilling_to_provide_fafsa_information_indicator IS 'Indicates whether the student''s parents unwilling to provide their information, but the student doesn''t have an unusual circumstance that prevents them from contacting or obtaining their parents'' information, meaning that the student wants a financial aid administrator at their school to use their FAFSA information to determine their eligibility for a Direct Unsubsidized Loan only';
COMMENT ON COLUMN person.person_non_identifiable_demographics.education_verification_method IS 'The method by which the formal education is verified';
COMMENT ON COLUMN person.person_non_identifiable_demographics.homeless_primary_residence IS 'The primary nighttime residence of the students at the time the students are identified as homeless';
COMMENT ON COLUMN person.person_non_identifiable_demographics.education_highest_level IS 'The extent of formal instruction a person has received. The highest grade in school completed or its equivalent or the highest degree received.';
COMMENT ON COLUMN person.person_non_identifiable_demographics.source_system_key_value IS 'Unique identifier of this record in the source system';
COMMENT ON COLUMN person.person_non_identifiable_demographics.source_system_created_date IS 'Date the record was created in the source system';
COMMENT ON COLUMN person.person_non_identifiable_demographics.source_system_updated_date IS 'Date the record was last updated in the source system';
COMMENT ON COLUMN person.person_non_identifiable_demographics.source_system_deleted_date IS 'Date the record was deleted from the source system';
COMMENT ON COLUMN person.person_non_identifiable_demographics.created_by IS 'Person identifier that created the record';
COMMENT ON COLUMN person.person_non_identifiable_demographics.created_date IS 'Date and time record was created';
COMMENT ON COLUMN person.person_non_identifiable_demographics.updated_by IS 'Person identifier that updated the record';
COMMENT ON COLUMN person.person_non_identifiable_demographics.updated_date IS 'Date and time record was updated';
COMMENT ON COLUMN person.person_non_identifiable_demographics.deleted_by IS 'Person identifier that deleted the record';
COMMENT ON COLUMN person.person_non_identifiable_demographics.deleted_date IS 'Date and time record was deleted';

