    updated_by                                       BIGINT,
    updated_date                                     TIMESTAMP WITH TIME ZONE,
    deleted_by                                       BIGINT,
    deleted_date                                     TIMESTAMP WITH TIME ZONE,
    CONSTRAINT pk_person_organization_membership PRIMARY KEY (tenant_identifier, person_organization_membership_identifier)
);
COMMENT ON TABLE person.person_organization_membership IS 'Tenant-scoped fact representing a person''s membership, participation, or role in an organization, optionally bounded by an academic term and start/end dates. Distinct from a general activity definition and from employment or academic enrollment relationships.';
COMMENT ON COLUMN person.person_organization_membership.tenant_identifier IS 'UUID identifying the tenant data-ownership and security boundary for this record.';
