COMMENT ON COLUMN person.person_organization_membership.source_system_deleted_date IS 'Date the record was deleted from the source system.';
COMMENT ON COLUMN person.person_organization_membership.created_by IS 'Person identifier that created the record.';
COMMENT ON COLUMN person.person_organization_membership.created_date IS 'Date and time record was created.';
COMMENT ON COLUMN person.person_organization_membership.updated_by IS 'Person identifier that updated the record.';
COMMENT ON COLUMN person.person_organization_membership.updated_date IS 'Date and time record was updated.';
COMMENT ON COLUMN person.person_organization_membership.deleted_by IS 'Person identifier that deleted the record.';
COMMENT ON COLUMN person.person_organization_membership.deleted_date IS 'Date and time record was deleted.';

