-- PersonRelatedContact
-- Stores limited information about a related or supporting contact who is not necessarily modeled
-- as a GUIDE Person, including relationship/role, priority, one selected phone/contact method, one
-- selected contact type, limited family-background facts, and source-group lineage. When multiple
-- source phones or contact types are supplied, GUIDE intentionally retains only the first
-- applicable value rather than creating repeated child rows.
CREATE TABLE person.person_related_contact (
    tenant_identifier                                UUID NOT NULL,
    person_identifier                                TEXT NOT NULL,
    sequence_number                                  TEXT NOT NULL,
    contact_type_identifier                          TEXT,
    relationship_type_identifier                     TEXT,
    contact_role_identifier                          TEXT,
    contact_priority_number                          INTEGER,
    contact_name                                     TEXT,
    first_name                                       TEXT,
    last_name                                        TEXT,
    primary_contact_indicator                        BOOLEAN DEFAULT FALSE,
    primary_guardian_indicator                       BOOLEAN DEFAULT FALSE,
    emergency_contact_indicator                      BOOLEAN DEFAULT FALSE,
    authorized_contact_indicator                     BOOLEAN DEFAULT FALSE,
    lives_with_indicator                             BOOLEAN DEFAULT FALSE,
    same_address_indicator                           BOOLEAN DEFAULT FALSE,
    deceased_indicator                               BOOLEAN DEFAULT FALSE,
    can_contact_indicator                            BOOLEAN DEFAULT TRUE,
    email_address                                    TEXT,
    phone_number                                     TEXT,
    address_line1                                    TEXT,
    address_line2                                    TEXT,
    city                                             TEXT,
    state_province                                   TEXT,
    postal_code                                      TEXT,
    country_code                                     TEXT,
    highest_education_level_identifier               TEXT,
    college_attended_indicator                       BOOLEAN DEFAULT FALSE,
    college_name                                     TEXT,
    degree_earned_indicator                          BOOLEAN DEFAULT FALSE,
    highest_degree_identifier                        TEXT,
    employer_name                                    TEXT,
    occupation_text                                  TEXT,
    institution_employee_indicator                   BOOLEAN DEFAULT FALSE,
    source_raw_contact_type                          TEXT,
    source_raw_relationship_type                     TEXT,
    source_raw_contact_role                          TEXT,
    source_raw_education_level                       TEXT,
    source_raw_college_name                          TEXT,
    source_raw_degree                                TEXT,
    source_raw_employer                              TEXT,
    source_system_identifier                         TEXT,
    source_system_key_value                          TEXT,
    created_by                                       BIGINT,
    created_date                                     TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_by                                       BIGINT,
    updated_date                                     TIMESTAMP WITH TIME ZONE,
    deleted_by                                       BIGINT,
    deleted_date                                     TIMESTAMP WITH TIME ZONE,
    middle_name                                      TEXT,
    phone_country_calling_code                       TEXT,
    phone_extension                                  TEXT,
    contact_availability_text                        TEXT,
    contact_address_text                             TEXT,
    CONSTRAINT pk_person_related_contact PRIMARY KEY (tenant_identifier, person_identifier, sequence_number)
);
COMMENT ON TABLE person.person_related_contact IS 'Stores limited information about a related or supporting contact who is not necessarily modeled as a GUIDE Person, including relationship/role, priority, one selected phone/contact method, one selected contact type, limited family-background facts, and source-group lineage. When multiple source phones or contact types are supplied, GUIDE intentionally retains only the first applicable value rather than creating repeated child rows.';
COMMENT ON COLUMN person.person_related_contact.tenant_identifier IS 'UUID identifying the tenant data-ownership and security boundary for this record.';
COMMENT ON COLUMN person.person_related_contact.person_identifier IS 'Tenant-scoped identifier for the learner or person to whom the related contact belongs.';
COMMENT ON COLUMN person.person_related_contact.sequence_number IS 'Tenant-local sequence distinguishing related-contact rows for the same person. For grouped source resources, assign deterministically within the person/source contact set; it is not a source-issued durable identifier.';
COMMENT ON COLUMN person.person_related_contact.contact_type_identifier IS 'Reference-code value identifying the broad category of related contact.';
COMMENT ON COLUMN person.person_related_contact.relationship_type_identifier IS 'Reference-code value identifying who the contact is in relation to the person.';
COMMENT ON COLUMN person.person_related_contact.contact_role_identifier IS 'Reference-code value identifying the functional role the contact plays for the person.';
COMMENT ON COLUMN person.person_related_contact.contact_priority_number IS 'Source or institutional priority/order for the contact, such as Guardian 1 or Guardian 2.';
COMMENT ON COLUMN person.person_related_contact.contact_name IS 'Source-supplied or displayable full name of the related contact.';
COMMENT ON COLUMN person.person_related_contact.first_name IS 'Structured given name of the related contact when supplied or reliably parsed.';
COMMENT ON COLUMN person.person_related_contact.last_name IS 'Structured family name of the related contact when supplied or reliably parsed.';
COMMENT ON COLUMN person.person_related_contact.primary_contact_indicator IS 'Indicates whether this contact is treated as the primary contact for the person.';
COMMENT ON COLUMN person.person_related_contact.primary_guardian_indicator IS 'Indicates whether this contact is treated as the primary guardian for the person.';
COMMENT ON COLUMN person.person_related_contact.emergency_contact_indicator IS 'Indicates whether this contact may be used as an emergency contact.';
COMMENT ON COLUMN person.person_related_contact.authorized_contact_indicator IS 'Indicates whether this contact is authorized for appropriate institutional contact under local policy.';
COMMENT ON COLUMN person.person_related_contact.lives_with_indicator IS 'Indicates whether the person is recorded as living with this related contact.';
COMMENT ON COLUMN person.person_related_contact.same_address_indicator IS 'Indicates whether this related contact shares the same address as the person.';
COMMENT ON COLUMN person.person_related_contact.deceased_indicator IS 'Indicates whether the related contact is recorded as deceased.';
COMMENT ON COLUMN person.person_related_contact.can_contact_indicator IS 'Indicates whether the institution may contact this related contact for the recorded purpose.';
COMMENT ON COLUMN person.person_related_contact.email_address IS 'Email address for the related contact when supplied.';
COMMENT ON COLUMN person.person_related_contact.phone_number IS 'Phone number retained for the related contact. If multiple source phones are supplied, retain only the first phone occurrence in deterministic source order.';
COMMENT ON COLUMN person.person_related_contact.address_line1 IS 'First address line for the related contact when supplied.';
COMMENT ON COLUMN person.person_related_contact.address_line2 IS 'Second address line for the related contact when supplied.';
COMMENT ON COLUMN person.person_related_contact.city IS 'City for the related contact address.';
COMMENT ON COLUMN person.person_related_contact.state_province IS 'State, province, or region for the related contact address.';
COMMENT ON COLUMN person.person_related_contact.postal_code IS 'Postal or ZIP code for the related contact address.';
COMMENT ON COLUMN person.person_related_contact.country_code IS 'ISO 3166-1 alpha-2 country or jurisdiction code associated with the related-contact address.';
COMMENT ON COLUMN person.person_related_contact.highest_education_level_identifier IS 'Reference-code value identifying the highest known education level for the related contact.';
COMMENT ON COLUMN person.person_related_contact.college_attended_indicator IS 'Indicates whether the related contact is recorded as having attended college.';
COMMENT ON COLUMN person.person_related_contact.college_name IS 'Name of the college or institution attended by the related contact, when supplied.';
COMMENT ON COLUMN person.person_related_contact.degree_earned_indicator IS 'Indicates whether the related contact is recorded as having earned a degree.';
COMMENT ON COLUMN person.person_related_contact.highest_degree_identifier IS 'Reference-code value identifying the highest known degree earned by the related contact.';
COMMENT ON COLUMN person.person_related_contact.employer_name IS 'Name of the related contact employer when supplied.';
COMMENT ON COLUMN person.person_related_contact.occupation_text IS 'Free-text occupation, job title, or employment description for the related contact.';
COMMENT ON COLUMN person.person_related_contact.institution_employee_indicator IS 'Indicates whether the related contact is recorded as an employee of the institution.';
COMMENT ON COLUMN person.person_related_contact.source_raw_contact_type IS 'Selected original source-system contact-type value. If multiple source contact types are supplied, retain only the first available type for the related contact.';
COMMENT ON COLUMN person.person_related_contact.source_raw_relationship_type IS 'Original source-system value for the relationship type, before DHSS reference-code interpretation.';
COMMENT ON COLUMN person.person_related_contact.source_raw_contact_role IS 'Original source-system value for the contact role, before DHSS reference-code interpretation.';
COMMENT ON COLUMN person.person_related_contact.source_raw_education_level IS 'Original source-system value for the related contact education level.';
COMMENT ON COLUMN person.person_related_contact.source_raw_college_name IS 'Original source-system value for the related contact college name.';
COMMENT ON COLUMN person.person_related_contact.source_raw_degree IS 'Original source-system value for the related contact degree.';
COMMENT ON COLUMN person.person_related_contact.source_raw_employer IS 'Original source-system value for the related contact employer.';
COMMENT ON COLUMN person.person_related_contact.source_system_identifier IS 'Identifier for the source system from which the related-contact row was imported or reconciled.';
COMMENT ON COLUMN person.person_related_contact.source_system_key_value IS 'Identifier of the source resource or source grouping from which the related-contact row was derived. It may repeat across multiple related-contact rows and is not the canonical row identity.';
COMMENT ON COLUMN person.person_related_contact.created_by IS 'Person identifier that created the record';
COMMENT ON COLUMN person.person_related_contact.created_date IS 'Date and time the related-contact row was created in DHSS.';
COMMENT ON COLUMN person.person_related_contact.updated_by IS 'Person identifier that updated the record';
COMMENT ON COLUMN person.person_related_contact.updated_date IS 'Date and time the related-contact row was last updated in DHSS.';
COMMENT ON COLUMN person.person_related_contact.deleted_by IS 'Person identifier that deleted the record';
COMMENT ON COLUMN person.person_related_contact.deleted_date IS 'Date and time the related-contact row was soft-deleted, if applicable.';
COMMENT ON COLUMN person.person_related_contact.middle_name IS 'Structured middle name of the related contact when supplied.';
COMMENT ON COLUMN person.person_related_contact.phone_country_calling_code IS 'Country calling code associated with the retained first related-contact phone occurrence.';
COMMENT ON COLUMN person.person_related_contact.phone_extension IS 'Extension associated with the retained first related-contact phone occurrence.';
COMMENT ON COLUMN person.person_related_contact.contact_availability_text IS 'Source-supplied best-time or availability note associated with the retained first related-contact phone occurrence.';
COMMENT ON COLUMN person.person_related_contact.contact_address_text IS 'Source-formatted full address for the related contact when reliable structured parsing is unavailable.';

-- PersonResidency
-- A table containing details of the person's residency declarations.
CREATE TABLE person.person_residency (
