    deferred_action_for_childhood_arrivals_status_indicator BOOLEAN,
    temporary_protected_status_indicator             BOOLEAN,
    congressional_district                           TEXT,
    county_fips_code                                 TEXT,
    publish_indicator                                BOOLEAN NOT NULL DEFAULT FALSE,
    residence_setting                                TEXT,
    residence_verification                           TEXT,
    record_start_date                                TIMESTAMP WITH TIME ZONE,
    record_end_date                                  TIMESTAMP WITH TIME ZONE,
    source_system_key_value                          TEXT,
    source_system_created_date                       DATE,
    source_system_updated_date                       DATE,
    source_system_deleted_date                       DATE,
    created_by                                       BIGINT NOT NULL,
    created_date                                     TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_by                                       BIGINT,
    updated_date                                     TIMESTAMP WITH TIME ZONE,
    deleted_by                                       BIGINT,
    deleted_date                                     TIMESTAMP WITH TIME ZONE,
    residency_type_identifier                        TEXT,
    administrative_period_identifier                 TEXT,
    CONSTRAINT pk_person_residency PRIMARY KEY (tenant_identifier, person_residency_identifier)
);
COMMENT ON TABLE person.person_residency IS 'A table containing details of the person''s residency declarations.';
COMMENT ON COLUMN person.person_residency.tenant_identifier IS 'UUID identifying the tenant data-ownership and security boundary for this record.';
COMMENT ON COLUMN person.person_residency.person_identifier IS 'A unique number or alphanumeric code assigned to a person';
COMMENT ON COLUMN person.person_residency.person_residency_identifier IS 'Unique identifier for a learner residency item';
COMMENT ON COLUMN person.person_residency.source_system_identifier IS 'Unique identifier for the source system';
COMMENT ON COLUMN person.person_residency.united_states_citizenship_status IS 'An indicator of whether or not the person is a US citizen (e.g. USCitizen, PermanentResident, ResidentAlien, NonResidentAlien, Refugee)';
COMMENT ON COLUMN person.person_residency.visa_type IS 'An indicator of a non-US citizen''s Visa type';
COMMENT ON COLUMN person.person_residency.tuition_residency_type IS 'A person''s residency status for tuition purposes';
COMMENT ON COLUMN person.person_residency.campus_residency_type IS 'A person''s residency arrangement as defined in the Free Application for Federal Student Aid (FAFSA)';
COMMENT ON COLUMN person.person_residency.legal_resident_of_state_start_date IS 'The month and year in which legal residency of the state began for the person';
COMMENT ON COLUMN person.person_residency.united_states_residency_start_date IS 'US residency start date';
COMMENT ON COLUMN person.person_residency.deferred_action_for_childhood_arrivals_status_indicator IS 'Indicates whether the individual has Deferred Action for Childhood Arrivals (DACA) status in the United States';
COMMENT ON COLUMN person.person_residency.temporary_protected_status_indicator IS 'Indicates whether the individual has Temporary Protected Status (TPS) as designated by the Secretary of Homeland Security or United States Citizenship and Immigration Resources (USCIS)';
COMMENT ON COLUMN person.person_residency.congressional_district IS 'The congressional district in which an address is located';
COMMENT ON COLUMN person.person_residency.county_fips_code IS 'The Federal Information Processing Standards (FIPS) numeric code for the county issued by the National Institute of Standards and Technology (NIST). Counties are considered to be the "first-order subdivisions" of each State and statistically equivalent entity, regardless of their local designations (county, parish, borough, etc.) Counties in different States will have the same code. A unique county number is created when combined with the 2-digit FIPS State Code.';
COMMENT ON COLUMN person.person_residency.publish_indicator IS 'An indication that the address should be published to a visible directory, application, or website, etc.';
COMMENT ON COLUMN person.person_residency.residence_setting IS 'A general geographic indicator that categorizes U.S. territory (e.g. City, Suburban)';
COMMENT ON COLUMN person.person_residency.residence_verification IS 'An accepted form of proof of residency in the district/county/other locality';
COMMENT ON COLUMN person.person_residency.record_start_date IS 'The effective date for which the address is valid. For physical addresses, the periods in which the person lived at that address.';
COMMENT ON COLUMN person.person_residency.record_end_date IS 'The expired date for which the address is valid. For physical addresses, the periods in which the person lived at that address.';
COMMENT ON COLUMN person.person_residency.source_system_key_value IS 'Unique identifier of this record in the source system';
COMMENT ON COLUMN person.person_residency.source_system_created_date IS 'Date the record was created in the source system';
COMMENT ON COLUMN person.person_residency.source_system_updated_date IS 'Date the record was last updated in the source system';
COMMENT ON COLUMN person.person_residency.source_system_deleted_date IS 'Date the record was deleted from the source system';
COMMENT ON COLUMN person.person_residency.created_by IS 'Person identifier that created the record';
COMMENT ON COLUMN person.person_residency.created_date IS 'Date and time record was created';
COMMENT ON COLUMN person.person_residency.updated_by IS 'Person identifier that updated the record';
COMMENT ON COLUMN person.person_residency.updated_date IS 'Date and time record was updated';
COMMENT ON COLUMN person.person_residency.deleted_by IS 'Person identifier that deleted the record';
COMMENT ON COLUMN person.person_residency.deleted_date IS 'Date and time record was deleted';
COMMENT ON COLUMN person.person_residency.residency_type_identifier IS 'Governed residency type.';
COMMENT ON COLUMN person.person_residency.administrative_period_identifier IS 'Starting administrative period for the residency determination.';

-- PersonServiceRestriction
-- An institutionally imposed restriction assigned to a person for a governed reason. The
-- restriction may be date- or term-scoped and may be affirmatively released. Current effectiveness
-- is derived from its effective period and release rather than stored as a generic status.
CREATE TABLE person.person_service_restriction (
    tenant_identifier                                UUID NOT NULL,
    person_service_restriction_identifier            TEXT NOT NULL,
    person_identifier                                TEXT NOT NULL,
    service_restriction_reason_identifier            TEXT NOT NULL,
    start_term_identifier                            TEXT,
    end_term_identifier                              TEXT,
    effective_start_date                             DATE,
    effective_end_date                               DATE,
    release_date                                     TIMESTAMP WITH TIME ZONE,
    responsible_organization_unit_identifier         TEXT,
    comments                                         TEXT,
    source_system_identifier                         TEXT,
