-- SuccessPredictionModel
-- Tenant-scoped definition of a predictive model used to estimate a learner outcome such as
-- persistence, retention, completion, or graduation. Model identity and interpretation are
-- separated from individual learner prediction results.
CREATE TABLE person.success_prediction_model (
    tenant_identifier                                UUID NOT NULL,
    success_prediction_model_identifier              TEXT NOT NULL,
    source_system_identifier                         TEXT,
    name                                             TEXT NOT NULL,
    target_outcome                                   TEXT NOT NULL,
    model_version                                    TEXT,
    time_horizon_description                         TEXT,
    description                                      TEXT,
    source_system_key_value                          TEXT,
    created_by                                       BIGINT NOT NULL,
    created_date                                     TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_by                                       BIGINT,
    updated_date                                     TIMESTAMP WITH TIME ZONE,
    deleted_by                                       BIGINT,
    deleted_date                                     TIMESTAMP WITH TIME ZONE,
    CONSTRAINT pk_success_prediction_model PRIMARY KEY (tenant_identifier, success_prediction_model_identifier)
);
COMMENT ON TABLE person.success_prediction_model IS 'Tenant-scoped definition of a predictive model used to estimate a learner outcome such as persistence, retention, completion, or graduation. Model identity and interpretation are separated from individual learner prediction results.';
COMMENT ON COLUMN person.success_prediction_model.tenant_identifier IS 'UUID identifying the tenant data-ownership and security boundary for this record.';
COMMENT ON COLUMN person.success_prediction_model.success_prediction_model_identifier IS 'Unique identifier for the learner success prediction model.';
COMMENT ON COLUMN person.success_prediction_model.source_system_identifier IS 'Optional source system from which the model definition was obtained.';
COMMENT ON COLUMN person.success_prediction_model.name IS 'Human-readable name of the prediction model.';
COMMENT ON COLUMN person.success_prediction_model.target_outcome IS 'Higher-education outcome the model is intended to predict, such as persistence, retention, completion, or graduation.';
COMMENT ON COLUMN person.success_prediction_model.model_version IS 'Optional source- or institution-defined model version.';
COMMENT ON COLUMN person.success_prediction_model.time_horizon_description IS 'Optional description of the outcome horizon used by the model, such as next academic term or completion within six years.';
COMMENT ON COLUMN person.success_prediction_model.description IS 'Narrative description of the model and the interpretation of its outputs.';
COMMENT ON COLUMN person.success_prediction_model.source_system_key_value IS 'Identifier of the model definition in the source system.';
COMMENT ON COLUMN person.success_prediction_model.created_by IS 'Person identifier that created the record';
COMMENT ON COLUMN person.success_prediction_model.created_date IS 'Date and time record was created';
COMMENT ON COLUMN person.success_prediction_model.updated_by IS 'Person identifier that updated the record';
COMMENT ON COLUMN person.success_prediction_model.updated_date IS 'Date and time record was updated';
COMMENT ON COLUMN person.success_prediction_model.deleted_by IS 'Person identifier that deleted the record';
COMMENT ON COLUMN person.success_prediction_model.deleted_date IS 'Date and time record was deleted';
